12	/// </summary>
13	internal static class SqlServerTestDatabase
14	{
15	    public static string BuildConnectionString(string discriminator)
16	    {
17	        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
18	            ?? throw new InvalidOperationException(
19	                "ConnectionStrings__Default ist nicht gesetzt. Die Backend-Tests benötigen eine erreichbare SQL-Server-Instanz.");
20	
21	        var builder = new SqlConnectionStringBuilder(baseConnectionString)
22	        {
23	            InitialCatalog = new SqlConnectionStringBuilder(baseConnectionString).InitialCatalog + "_" + discriminator
24	        };
25	        return builder.ConnectionString;
26	    }
27	
28	    public static async Task<AppDbContext> CreateFreshContextAsync(string discriminator)
29	    {
30	        var options = new DbContextOptionsBuilder<AppDbContext>()
31	            .UseSqlServer(BuildConnectionString(discriminator))
32	            .Options;
33	
34	        var db = new AppDbContext(options);
35	        await db.Database.EnsureDeletedAsync();
36	        await db.Database.MigrateAsync();
37	        return db;
38	    }
39	
40	    public static async Task DropAsync(string discriminator)
41	    {
42	        var options = new DbContextOptionsBuilder<AppDbContext>()
43	            .UseSqlServer(BuildConnectionString(discriminator))
44	            .Options;
45	
46	        await using var db = new AppDbContext(options);
47	        await db.Database.EnsureDeletedAsync();
48	    }
49	}
